// ---- the kernel ----
__global__ void __launch_bounds__(256, 1)
    layer_kernel(const __grid_constant__ static_mk::Maps maps,
                 static_mk::G g,
                 StaticTask const *static_tasks) {
  static_mk::KernelLocals L;
  static_mk::kernel_begin(g, L);
  StaticTask const *my =
      static_tasks + blockIdx.x * (static_mk::MAX_TASKS_PER_SM);
  bool warm_9 = false;  // a task of node 9 ran on this SM: its code is in the
                        // instruction cache
  bool warm_53 = false; // a task of node 53 ran on this SM: its code is in the
                        // instruction cache
  bool warm_59 = false; // a task of node 59 ran on this SM: its code is in the
                        // instruction cache
  bool warm_68 = false; // a task of node 68 ran on this SM: its code is in the
                        // instruction cache
  bool warm_70 = false; // a task of node 70 ran on this SM: its code is in the
                        // instruction cache
  for (int ti = 0; ti < static_mk::MAX_TASKS_PER_SM; ti++) {
    StaticTask const tk = my[ti];
    if (tk.node < 0) {
      break;
    }
    switch (tk.node) {
      case 3:
        static_mk::run_act_quant<StaticNode<8, 2, 1, 0, 1>,
                                 StaticParams<5120>,
                                 StaticBufSlots<0>,
                                 StaticMapSlots<>,
                                 StaticNode<0, 0, 0>>(maps, g, L, tk);
