                       {"buf.12", "tensor cmp_norm_weight 512 -1 0"},
                       {"buf.13", "tensor cmp_state 16384 -1 0"},
                       {"buf.14", "out latent 8192 -1 0"},
                       {"buf.15", "tensor compress_cache 4718592 -1 0"},
                       {"buf.16", "out wk_part 4096 255 1"},
