    {"layout_func",
     py_layout,
     METH_NOARGS,
     "the sizes of the instrumentation buffers"},
    {"finalize_func", py_finalize, METH_NOARGS, "free everything"},
    {NULL, NULL, 0, NULL}};
static struct PyModuleDef StaticModuleDef = {PyModuleDef_HEAD_INIT,
                                             "__mirage_static_launcher",
                                             NULL,
                                             -1,
                                             StaticMethods,
                                             NULL,
                                             NULL,
                                             NULL,
                                             NULL};
PyMODINIT_FUNC PyInit___mirage_static_launcher(void) {
  return PyModule_Create(&StaticModuleDef);
}
